{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.pronk_sku_profitability_report as with all_sku_dates as ( SELECT DISTINCT upper(SKU) sku, c.date_day, d.final_marketplace marketplace, FROM pronk-wh.maplemonk.pronk_SALES_CONSOLIDATED d CROSS JOIN ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE \'2024-01-01\', CURRENT_DATE())) AS date_day ) AS c ) select fi.sku, fi.date_day, fi.marketplace, maplemonk.get_category(ifnull(fi.sku,\'\')) as Product_Category, maplemonk.get_sub_category(ifnull(fi.sku,\'\')) as Product_Sub_Category, maplemonk.get_color(ifnull(fi.sku,\'\')) as Product_Colour, maplemonk.get_size(ifnull(fi.sku,\'\')) as Product_Size, maplemonk.get_dt_code(ifnull(fi.sku,\'\')) as Product_DT_Code, maplemonk.get_gender(ifnull(fi.sku,\'\')) as Gender, total_sales, total_quantity, total_orders, i.avg_grn_cost as grn_cost, case when (maplemonk.get_dt_code(ifnull(fi.sku,\'\')) is null or maplemonk.get_dt_code(ifnull(fi.sku,\'\')) = \'NA\') then i.avg_grn_cost else (i.avg_grn_cost + 60) end as avg_grn_cost from all_sku_dates FI left join (select upper(sku) sku, date(order_date) date, upper(final_marketplace) as marketplace, sum(ifnull(selling_price,0)) as total_sales, sum(ifnull(quantity,0)) as total_quantity, count(distinct order_id) as total_orders from maplemonk.pronk_sales_consolidated where rto_flag = 0 and dto_flag = 0 and (order_status is null or not(order_status like any (\'%cancel%\',\'%return%\',\'%undelivered%\',\'%exchange%\'))) and (oms_order_status is null or not(oms_order_status like any (\'%cancel%\',\'%return%\',\'%undelivered%\',\'%exchange%\'))) and (final_shipping_status is null or not(final_shipping_status like any (\'%cancel%\',\'%return%\',\'%undelivered%\',\'%exchange%\'))) group by 1,2,3 ) s on s.sku = fi.sku and date(s.date) = date(fi.date_day) and lower(s.marketplace) = lower(fi.marketplace) left join (select upper(trim(sku)) as sku, avg(cast(grn_cost as float64)) as avg_grn_cost from maplemonk.Easyecom_full_inventory_report group by 1 qualify row_number() over (partition by sku order by 1)=1 )i on lower(maplemonk.get_sku_without_dt_code(i.sku)) = lower(maplemonk.get_sku_without_dt_code(fi.sku)) ; create or replace table maplemonk.pronk_daily_profitability_report as with all_sku_dates as ( SELECT DISTINCT d.sku, c.date_day, d.final_marketplace marketplace FROM pronk-wh.maplemonk.pronk_SALES_CONSOLIDATED d CROSS JOIN ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE \'2024-01-01\', CURRENT_DATE())) AS date_day ) AS c ), grn_cost_daily as ( select fi.marketplace, fi.date_day, sum(ifnull(i.avg_grn_cost,0) * ifnull(total_quantity,0)) as grn_cost, sum(ifnull((case when (maplemonk.get_dt_code(ifnull(fi.sku,\'\')) is null or maplemonk.get_dt_code(ifnull(fi.sku,\'\')) = \'NA\') then i.avg_grn_cost else (i.avg_grn_cost + 60) end),0) * ifnull(total_quantity,0)) as avg_grn_cost from all_sku_dates FI left join (select upper(sku) sku, date(order_date) date, upper(final_marketplace) as marketplace, sum(ifnull(quantity,0)) as total_quantity from maplemonk.pronk_sales_consolidated where rto_flag = 0 and dto_flag = 0 and (order_status is null or not(order_status like any (\'%cancel%\',\'%return%\',\'%undelivered%\',\'%exchange%\'))) and (oms_order_status is null or not(oms_order_status like any (\'%cancel%\',\'%return%\',\'%undelivered%\',\'%exchange%\'))) and (final_shipping_status is null or not(final_shipping_status like any (\'%cancel%\',\'%return%\',\'%undelivered%\',\'%exchange%\'))) group by 1,2,3 ) s on s.sku = fi.sku and date(s.date) = date(fi.date_day) and lower(s.marketplace) = lower(fi.marketplace) left join (select upper(trim(sku)) as sku, avg(cast(grn_cost as float64)) as avg_grn_cost from maplemonk.Easyecom_full_inventory_report group by 1 qualify row_number() over (partition by sku order by 1)=1 )i on lower(maplemonk.get_sku_without_dt_code(i.sku)) = lower(maplemonk.get_sku_without_dt_code(fi.sku)) group by 1,2 ) select fi.date_day, fi.marketplace, avg(ifnull(total_sales,0)) total_sales, avg(ifnull(total_quantity,0)) total_quantity, avg(ifnull(total_orders,0)) total_orders, avg(ifnull(g.grn_cost,0)) grn_cost, avg(ifnull(g.avg_grn_cost,0)) avg_grn_cost, avg(ifnull(m.spend,0)) as adv_spends from all_sku_dates FI left join (select date(order_date) date, upper(final_marketplace) as marketplace, sum(ifnull(selling_price,0)) as total_sales, sum(ifnull(quantity,0)) as total_quantity, count(distinct order_id) as total_orders from maplemonk.pronk_sales_consolidated where rto_flag = 0 and dto_flag = 0 and (order_status is null or not(order_status like any (\'%cancel%\',\'%return%\',\'%undelivered%\',\'%exchange%\'))) and (oms_order_status is null or not(oms_order_status like any (\'%cancel%\',\'%return%\',\'%undelivered%\',\'%exchange%\'))) and (final_shipping_status is null or not(final_shipping_status like any (\'%cancel%\',\'%return%\',\'%undelivered%\',\'%exchange%\'))) group by 1,2 ) s on date(s.date) = date(fi.date_day) and lower(s.marketplace) = lower(fi.marketplace) left join grn_cost_daily g on date(s.date) = date(g.date_day) and lower(s.marketplace) = lower(g.marketplace) left join (select date, case when lower(channel) like any (\'%facebook%\', \'%google%\') then \'WEBSITE\' when lower(channel) like any (\'%amazon%\') then \'AMAZON\' when lower(channel) like \'%flipkart%\' then \'FLIPKART\' when lower(channel) like \'%myntra%\' then \'MYNTRA\' else upper(channel) end as Marketplace, sum(ifnull(spend,0)) as spend from pronk-wh.maplemonk.pronk_MARKETING_CONSOLIDATED group by 1,2) m on m.date = fi.date_day and lower(m.marketplace) = lower(fi.marketplace) group by 1,2 ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
